import XCTest

final class TapComposeTests: XCTestCase {
    func testTapComposeButton() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)
        let origin = app.coordinate(withNormalizedOffset: CGVector(dx: 0, dy: 0))
        let target = origin.withOffset(CGVector(dx: 0.928 * app.frame.width, dy: 0.934 * app.frame.height))
        target.tap()
        sleep(2)
    }
}

